def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'

    my_def = 0
    opp_def = 0
    soft = 0
    hostile = 0
    tail = 0
    recent_def = 0

    for i in range(n):
        if history[i][0] == 'D':
            my_def += 1
        if history[i][1] == 'D':
            opp_def += 1

    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                soft += 1
            else:
                hostile += 1

    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            tail += 1
        else:
            break

    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_def += 1

    last_opp = history[-1][1]
    prev_my = history[-2][0]

    if my_def == 0 and opp_def == 0 and n >= 30:
        return 'D'

    if opp_def * 2 >= n or tail >= 5 or recent_def >= 6:
        return 'D'

    if (soft > hostile * 3 and opp_def * 4 < n and
            recent_def <= 2 and tail == 0 and last_opp == 'C'):
        return 'D'

    if last_opp == 'D':
        if prev_my == 'D':
            if opp_def * 4 < n and tail <= 2:
                return 'C'
            return 'D'
        return 'D'

    return 'C'
